import java.util.*;
abstract class Process{
    int pid;
    int bt;

    Process(int pid,int bt){
        this.pid=pid;
        this.bt=bt;
    }

    abstract int calculateTime();

    void displayDetails(){
        System.out.println("Process ID: "+pid);
        System.out.println("Burst Time: "+bt+" ms");
        System.out.println("Execution Time: "+bt+2+" ms");
    }
}

class CPUProcess extends Process{
    CPUProcess(int pid,int bt){
        super(pid,bt);
    }
    int calculateTime(){
        return bt+2;
    }
}

public class Main{
    public static void main(String[] args){
        Scanner in=new Scanner(System.in);
        int pid=in.nextInt();
        int bt=in.nextInt();
        Process p=new CPUProcess(pid,bt);
        p.displayDetails();
        p.calculateTime();
    }
}

